code_example:
#include <iostream>
#include <type_traits>
template <typename T, typename = std::enable_if_t<std::is_integral_v<T>>>
int processInteger(T value) {
  return value * 2;
}

template <typename T, typename = std::enable_if_t<std::is_floating_point_v<T>>>
double processFloatingPoint(T value) {
  return value * 2.0;
}
int main() {
  std::cout << processInteger(5) << std::endl; // Calls processInteger<int>
  std::cout << processFloatingPoint(5.5) << std::endl; // Calls processFloatingPoint<double>
  //std::cout << processInteger(5.5) << std::endl; // Compilation error:  processInteger<double> is not enabled
  return 0;
}
